    def for_opponent?
      [1, 2, 3, 4, 5, 6].include?(@scope)
    end
    def for_friend?
      [7, 8, 9, 10, 11].include?(@scope)
    end
    def for_dead_friend?
      [9, 10].include?(@scope)
    end
    def for_user?
      @scope == 11
    end
    def for_one?
      [1, 3, 7, 9, 11].include?(@scope)
    end
    def for_random?
      [3, 4, 5, 6].include?(@scope)
    end
    def number_of_targets
      for_random? ? @scope - 2 : 0
    end
    def for_all?
      [2, 8, 10].include?(@scope)
    end
    def need_selection?
      [1, 7, 9].include?(@scope)
    end
    def battle_ok?
      [0, 1].include?(@occasion)
    end
    def menu_ok?
      [0, 2].include?(@occasion)
    end
    def certain?
      @hit_type == 0
    end
    def physical?
