}

varying vec4 v_color;
varying vec2 v_texCoord;
uniform sampler2D tex0;

void main()
{
    gl_FragColor = texture2D(tex0, v_texCoord);
    gl_FragColor.a = 1.0;
    gl_FragColor *= v_color;
}

varying vec4 v_color;
